package com.npcchatreplacement;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An immutable text-replacement rule.
 * <p>
 * Each rule targets a specific NPC (or all NPCs/players when {@code npcName} is {@code "*"})
 * and replaces occurrences of {@link #originalText} with {@link #replacementText} in
 * dialog and overhead chat.
 * <p>
 * Rules are created via the {@link ChatReplacementRule#builder()} and are not modified
 * after construction — a config change discards all existing rules and parses fresh ones.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor(access = AccessLevel.PACKAGE)
public class ChatReplacementRule
{
	/** The NPC name to match (case-insensitive). Use {@code "*"} to match all NPCs/players. */
	private String npcName;

	/** The word or phrase to find in chat text. */
	private String originalText;

	/** The word or phrase to replace matches with. */
	private String replacementText;

	/** Whether this rule is active. Disabled rules are skipped during replacement. */
	@Builder.Default
	private boolean enabled = true;

	/** Whether {@link #originalText} matching is case-sensitive. */
	@Builder.Default
	private boolean caseSensitive = false;

	/**
	 * Lazily compiled regex pattern built from {@link #originalText} and {@link #caseSensitive}.
	 * Marked {@code transient} to exclude from serialization.
	 */
	@lombok.EqualsAndHashCode.Exclude
	@lombok.ToString.Exclude
	private transient Pattern compiledPattern;

	/**
	 * Returns {@code true} if this rule applies to the given NPC/player name.
	 * A wildcard {@code npcName} of {@code "*"} matches everything.
	 */
	public boolean matchesNpc(String name)
	{
		if ("*".equals(npcName))
		{
			return true;
		}
		return npcName != null && npcName.equalsIgnoreCase(name);
	}

	/**
	 * Applies this rule's replacement to {@code text}.
	 * Returns the text unchanged if the rule is disabled or {@link #originalText} is empty.
	 */
	public String apply(String text)
	{
		if (!enabled || originalText == null || originalText.isEmpty() || text == null)
		{
			return text;
		}

		Pattern pattern = getOrCompilePattern();
		return pattern.matcher(text).replaceAll(
			Matcher.quoteReplacement(replacementText != null ? replacementText : "")
		);
	}

	private Pattern getOrCompilePattern()
	{
		if (compiledPattern == null)
		{
			String quoted = Pattern.quote(originalText);
			int flags = caseSensitive ? 0 : Pattern.CASE_INSENSITIVE;
			compiledPattern = Pattern.compile(quoted, flags);
		}
		return compiledPattern;
	}
}

package com.npcchatreplacement;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("npcchatreplacement")
public interface NpcChatReplacementConfig extends Config
{
	// ── Section: Toggles ─────────────────────────────────────────

	@ConfigSection(
		name = "Toggles",
		description = "Enable or disable different replacement targets",
		position = 0
	)
	String toggleSection = "toggles";

	@ConfigItem(
		keyName = "enableDialogReplacement",
		name = "Enable NPC/Player Dialog Replacement",
		description = "Replaces text in the NPC and player dialog interface",
		position = 1,
		section = toggleSection
	)
	default boolean enableDialogReplacement()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableOverheadReplacement",
		name = "Enable Overhead Replacement",
		description = "Replaces text in overhead speech bubbles",
		position = 2,
		section = toggleSection
	)
	default boolean enableOverheadReplacement()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableChatReplacement",
		name = "Enable Chat Replacement",
		description = "Replaces text in chatbox messages",
		position = 3,
		section = toggleSection
	)
	default boolean enableChatReplacement()
	{
		return true;
	}

	// ── Section: Replacement Rules ───────────────────────────────

	@ConfigSection(
		name = "Replacement Rules",
		description = "Define word/phrase replacements. One rule per line.",
		position = 10
	)
	String rulesSection = "replacementRules";

	@ConfigItem(
		keyName = "replacementRules",
		name = "Replacement Rules",
		description = "One rule per line. Format: NPC Name | Find Text | Replace Text"
			+ "<br/>Use * as NPC name to match all NPCs/players."
			+ "<br/>Lines starting with # are comments."
			+ "<br/>Examples:"
			+ "<br/>Allana | farming | plowing"
			+ "<br/>* | Hello | Howdy"
			+ "<br/>Guard | halt | stop right there",
		position = 11,
		section = rulesSection
	)
	default String replacementRules()
	{
		return "Yama | soul | left arm hair";
	}
}

package com.npcchatreplacement;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Chat Replacement",
	description = "Replace words in NPC and player dialog, overhead speech, and chat text",
	tags = {"npc", "chat", "replacement", "text", "dialog", "overhead"}
)
public class NpcChatReplacementPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private NpcChatReplacementConfig config;

	private ReplacementManager replacementManager;

	// Dedup guards — track what we last wrote so we don't re-replace our own output each tick
	private String lastChatLeftText = "";
	private String lastChatRightText = "";
	private String lastChatBothText = "";

	@Provides
	NpcChatReplacementConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NpcChatReplacementConfig.class);
	}

	@Override
	protected void startUp()
	{
		replacementManager = new ReplacementManager();
		replacementManager.parseRules(config.replacementRules());
		log.info("Chat Replacement started!");
	}

	@Override
	protected void shutDown()
	{
		log.info("Chat Replacement stopped!");
	}

	// ---------------------------------------------------------------
	// Config change
	// ---------------------------------------------------------------

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"npcchatreplacement".equals(event.getGroup()))
		{
			return;
		}

		if ("replacementRules".equals(event.getKey()))
		{
			replacementManager.parseRules(config.replacementRules());
			log.info("Replacement rules reloaded");
		}
	}

	// ---------------------------------------------------------------
	// Chat message replacement (chatbox text)
	// ---------------------------------------------------------------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final ChatMessageType type = event.getType();

		if (type == ChatMessageType.DIALOG && config.enableDialogReplacement())
		{
			replaceMessageNode(event);
		}
		else if ((type == ChatMessageType.NPC_SAY || type == ChatMessageType.PUBLICCHAT)
			&& config.enableChatReplacement())
		{
			replaceMessageNode(event);
		}
	}

	// ---------------------------------------------------------------
	// Overhead text replacement
	// ---------------------------------------------------------------

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!config.enableOverheadReplacement())
		{
			return;
		}

		final Actor actor = event.getActor();
		if (actor == null)
		{
			return;
		}

		final String name = actor.getName();
		if (name == null)
		{
			return;
		}

		final String original = event.getOverheadText();
		if (original == null)
		{
			return;
		}

		final String replaced = replacementManager.applyReplacements(name, original);
		if (!replaced.equals(original))
		{
			actor.setOverheadText(replaced);
		}
	}

	// ---------------------------------------------------------------
	// Dialog widget replacement — GameTick polling (the reliable way)
	// ---------------------------------------------------------------

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.enableDialogReplacement())
		{
			return;
		}

		replaceChatLeftWidget();
		replaceChatRightWidget();
		replaceChatBothWidget();
	}

	// ---------------------------------------------------------------
	// Dialog widget replacement — WidgetLoaded fast-path
	// ---------------------------------------------------------------

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!config.enableDialogReplacement())
		{
			return;
		}

		final int groupId = event.getGroupId();

		if (groupId == InterfaceID.CHAT_LEFT)
		{
			lastChatLeftText = "";
			clientThread.invokeLater(this::replaceChatLeftWidget);
		}
		else if (groupId == InterfaceID.CHAT_RIGHT)
		{
			lastChatRightText = "";
			clientThread.invokeLater(this::replaceChatRightWidget);
		}
		else if (groupId == InterfaceID.CHAT_BOTH)
		{
			lastChatBothText = "";
			clientThread.invokeLater(this::replaceChatBothWidget);
		}
	}

	// ---------------------------------------------------------------
	// CHAT_LEFT — NPC talking to player (chathead on left side)
	// Widget: InterfaceID.ChatLeft.NAME (packed), InterfaceID.ChatLeft.TEXT (packed)
	// ---------------------------------------------------------------

	private void replaceChatLeftWidget()
	{
		final Widget textWidget = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (textWidget == null || textWidget.isHidden())
		{
			return;
		}

		final String currentText = textWidget.getText();
		if (currentText == null || currentText.equals(lastChatLeftText))
		{
			return;
		}

		final Widget nameWidget = client.getWidget(InterfaceID.ChatLeft.NAME);
		final String npcName = (nameWidget != null && nameWidget.getText() != null)
			? nameWidget.getText()
			: "";

		final String replaced = replacementManager.applyReplacements(npcName, currentText);
		if (!replaced.equals(currentText))
		{
			textWidget.setText(replaced);
			lastChatLeftText = replaced;
		}
		else
		{
			lastChatLeftText = currentText;
		}
	}

	// ---------------------------------------------------------------
	// CHAT_RIGHT — Player talking (chathead on right side)
	// ---------------------------------------------------------------

	private void replaceChatRightWidget()
	{
		final Widget textWidget = client.getWidget(InterfaceID.ChatRight.TEXT);
		if (textWidget == null || textWidget.isHidden())
		{
			return;
		}

		final String currentText = textWidget.getText();
		if (currentText == null || currentText.equals(lastChatRightText))
		{
			return;
		}

		final Widget nameWidget = client.getWidget(InterfaceID.ChatRight.NAME);
		final String playerName = (nameWidget != null && nameWidget.getText() != null)
			? nameWidget.getText()
			: "";

		final String replaced = replacementManager.applyReplacements(playerName, currentText);
		if (!replaced.equals(currentText))
		{
			textWidget.setText(replaced);
			lastChatRightText = replaced;
		}
		else
		{
			lastChatRightText = currentText;
		}
	}

	// ---------------------------------------------------------------
	// CHAT_BOTH — Two characters talking (chatheads on both sides)
	// ---------------------------------------------------------------

	private void replaceChatBothWidget()
	{
		final Widget textWidget = client.getWidget(InterfaceID.ChatBoth.TEXT);
		if (textWidget == null || textWidget.isHidden())
		{
			return;
		}

		final String currentText = textWidget.getText();
		if (currentText == null || currentText.equals(lastChatBothText))
		{
			return;
		}

		final Widget namesWidget = client.getWidget(InterfaceID.ChatBoth.NAMES);
		final String names = (namesWidget != null && namesWidget.getText() != null)
			? namesWidget.getText()
			: "";

		final String replaced = replacementManager.applyReplacements(names, currentText);
		if (!replaced.equals(currentText))
		{
			textWidget.setText(replaced);
			lastChatBothText = replaced;
		}
		else
		{
			lastChatBothText = currentText;
		}
	}

	// ---------------------------------------------------------------
	// Chat message node replacement (for chatbox text)
	// ---------------------------------------------------------------

	private void replaceMessageNode(ChatMessage event)
	{
		final String name = event.getName();
		final String original = event.getMessage();

		if (name == null || original == null)
		{
			return;
		}

		final String replaced = replacementManager.applyReplacements(name, original);
		if (!replaced.equals(original))
		{
			event.getMessageNode().setValue(replaced);
		}
	}
}

package com.npcchatreplacement;

import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import lombok.extern.slf4j.Slf4j;

/**
 * Parses pipe-delimited replacement rules from a config string and applies them
 * to NPC/player chat text in order.
 * <p>
 * Config format (one rule per line):
 * <pre>
 *   NPC Name | Find Text | Replace Text
 *   # This is a comment
 * </pre>
 * Not a singleton, not injected — created manually by the plugin.
 */
@Slf4j
public class ReplacementManager
{
	private final CopyOnWriteArrayList<ChatReplacementRule> rules = new CopyOnWriteArrayList<>();

	/**
	 * Parses replacement rules from a multi-line config string.
	 * <p>
	 * Each non-empty, non-comment line must contain exactly three pipe-separated
	 * parts: {@code NPC Name | Find Text | Replace Text}. Malformed lines are
	 * logged as warnings and skipped.
	 * <p>
	 * Clears all existing rules before parsing.
	 *
	 * @param configText the raw config string, may be null
	 */
	public void parseRules(String configText)
	{
		rules.clear();

		if (configText == null || configText.isEmpty())
		{
			return;
		}

		String[] lines = configText.split("\n");

		for (int i = 0; i < lines.length; i++)
		{
			String line = lines[i].trim();

			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}

			String[] parts = line.split("\\|");

			if (parts.length != 3)
			{
				log.warn("Skipping malformed rule on line {} (expected 3 pipe-separated parts, got {}): {}",
					i + 1, parts.length, line);
				continue;
			}

			ChatReplacementRule rule = ChatReplacementRule.builder()
				.npcName(parts[0].trim())
				.originalText(parts[1].trim())
				.replacementText(parts[2].trim())
				.build();

			rules.add(rule);
		}

		log.debug("Parsed {} replacement rule(s)", rules.size());
	}

	/**
	 * Runs every enabled, NPC-matching rule against {@code text} in order and
	 * returns the final result. Returns the original text unchanged when no
	 * rules match or the inputs are null/empty.
	 */
	public String applyReplacements(String npcName, String text)
	{
		if (text == null || text.isEmpty())
		{
			return text;
		}

		String result = text;

		for (ChatReplacementRule rule : rules)
		{
			if (rule.isEnabled() && rule.matchesNpc(npcName))
			{
				result = rule.apply(result);
			}
		}

		return result;
	}

	/**
	 * Returns an unmodifiable view of the current rules.
	 */
	public List<ChatReplacementRule> getRules()
	{
		return Collections.unmodifiableList(rules);
	}
}

